import fs from 'fs';
import path from 'path';
import type { Framework } from '../services/ProjectDetectionService';

export const DEV_SCRIPT_CANDIDATES = [
  'dev',
  'start',
  'serve',
  'storybook',
] as const;

export const FRAMEWORK_DEV_CONFIG: Record<
  string,
  { devCommand: string; defaultPort: number }
> = {
  nextjs: { devCommand: 'dev', defaultPort: 3000 },
  vite: { devCommand: 'dev', defaultPort: 5173 },
  cra: { devCommand: 'start', defaultPort: 3000 },
  remix: { devCommand: 'dev', defaultPort: 3000 },
  svelte: { devCommand: 'dev', defaultPort: 5173 },
  static: { devCommand: '', defaultPort: 0 },
};

export function resolveDevScript(
  projectPath: string,
  framework: Framework,
): string {
  const fallback = FRAMEWORK_DEV_CONFIG[framework]?.devCommand ?? 'dev';
  try {
    const parsed = JSON.parse(
      fs.readFileSync(path.join(projectPath, 'package.json'), 'utf8'),
    ) as { scripts?: Record<string, unknown> };
    const scripts = parsed.scripts;
    if (!scripts || typeof scripts !== 'object') return fallback;
    if (typeof scripts[fallback] === 'string') return fallback;
    const candidate = DEV_SCRIPT_CANDIDATES.find(
      (name) => typeof scripts[name] === 'string',
    );
    return candidate ?? fallback;
  } catch {
    return fallback;
  }
}

export function buildDevServerCommand(
  framework: Framework,
  packageManager: string,
  devCommand: string,
  port: number,
): { cmd: string; args: string[]; env: Record<string, string> } {
  const env = { PORT: String(port) };
  if (framework === 'cra') {
    const args = packageManager === 'npm' ? ['run', devCommand] : [devCommand];
    return { cmd: packageManager, args, env };
  }
  if (packageManager === 'npm') {
    return {
      cmd: 'npm',
      args: ['run', devCommand, '--', '--port', String(port)],
      env,
    };
  }
  if (packageManager === 'yarn') {
    return { cmd: 'yarn', args: [devCommand, '--port', String(port)], env };
  }
  return { cmd: 'pnpm', args: [devCommand, '--port', String(port)], env };
}
